// Shadertoy 代码：三维球体与立方体变形效果
// 灯光位置随时间变化，形状从球体变为立方体，再变回球体

// SDF 函数：球体
float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

// SDF 函数：立方体
float sdBox(vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

// 形状插值函数
float smin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}

// 主函数
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // 归一化坐标到 [-1, 1]
    vec2 uv = fragCoord / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y; // 修正宽高比

    // 摄像机位置
    vec3 camPos = vec3(0.0, 0.0, 5.0);
    // 射线方向
    vec3 rayDir = normalize(vec3(uv, -1.0));

    // 变形动画控制
    float cycleTime = mod(iTime, 4.0); // 4 秒为一个周期
    float morphProgress = smoothstep(0.0, 1.0, abs(cycleTime - 2.0) / 2.0); // 0-2 秒球变立方体，2-4 秒立方体变球

    // 球体和立方体的 SDF 插值
    vec3 p = camPos + rayDir * 2.0; // 初始射线步进
    float sphere = sdSphere(p, 1.0);
    float box = sdBox(p, vec3(0.8));
    float shape = mix(sphere, box, morphProgress); // 根据 morphProgress 插值

    // 光线步进
    float t = 0.0;
    for (int i = 0; i < 100; i++) {
        vec3 pos = camPos + t * rayDir;
        float dist = mix(sdSphere(pos, 1.0), sdBox(pos, vec3(0.8)), morphProgress);
        if (dist < 0.001) break; // 接近表面时停止
        t += dist;
        if (t > 20.0) break; // 超出最大距离时停止
    }

    // 计算交点位置和法线
    vec3 hitPos = camPos + t * rayDir;
    vec3 normal;
    if (t < 20.0) {
        float eps = 0.001;
        normal = normalize(vec3(
            mix(sdSphere(hitPos + vec3(eps, 0, 0), 1.0), sdBox(hitPos + vec3(eps, 0, 0), vec3(0.8)), morphProgress) -
            mix(sdSphere(hitPos - vec3(eps, 0, 0), 1.0), sdBox(hitPos - vec3(eps, 0, 0), vec3(0.8)), morphProgress),
            mix(sdSphere(hitPos + vec3(0, eps, 0), 1.0), sdBox(hitPos + vec3(0, eps, 0), vec3(0.8)), morphProgress) -
            mix(sdSphere(hitPos - vec3(0, eps, 0), 1.0), sdBox(hitPos - vec3(0, eps, 0), vec3(0.8)), morphProgress),
            mix(sdSphere(hitPos + vec3(0, 0, eps), 1.0), sdBox(hitPos + vec3(0, 0, eps), vec3(0.8)), morphProgress) -
            mix(sdSphere(hitPos - vec3(0, 0, eps), 1.0), sdBox(hitPos - vec3(0, 0, eps), vec3(0.8)), morphProgress)
        ));
    } else {
        // 如果没有交点，返回背景色
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    // 灯光位置随时间变化
    float lightAngle = iTime * 0.5; // 灯光绕 y 轴旋转
    vec3 lightPos = vec3(3.0 * cos(lightAngle), 2.0, 3.0 * sin(lightAngle));

    // 计算光照
    vec3 lightDir = normalize(lightPos - hitPos);
    float diff = max(dot(normal, lightDir), 0.0);
    vec3 diffuse = diff * vec3(1.0, 0.8, 0.6); // 漫反射颜色

    // 环境光
    vec3 ambient = vec3(0.1, 0.1, 0.1);

    // 最终颜色
    vec3 color = ambient + diffuse;

    // 输出颜色
    fragColor = vec4(color, 1.0);
}
